package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.io.*;
public final class PcWorldMaterialReferenceExport {
 static void buffer(DataOutputStream out,ByteBuffer b)throws Exception{out.writeInt(b.remaining());byte[] bytes=new byte[b.remaining()];b.duplicate().get(bytes);out.write(bytes);}static void number(DataOutputStream out,double v)throws Exception{out.writeLong(Long.reverseBytes(Double.doubleToRawLongBits(v)));}
 public static void main(String[] args)throws Exception{Path output=Paths.get(args[1]);Files.createDirectories(output);int worlds=0,accepted=0,rejected=0,variants=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(Paths.get(args[0]),"*.nsp")){for(Path file:files){NativeScenePacket packet=new NativeScenePacket(1,Files.readAllBytes(file));NativeWorldScene world=new NativeWorldScene(packet);try(DataOutputStream out=new DataOutputStream(Files.newOutputStream(output.resolve(file.getFileName().toString().replace(".nsp",".material"))))){out.writeInt(world.surfaceCount());for(int i=0;i<world.surfaceCount();i++){NativeWorldScene.Surface s=world.surface(i);NativeLitWall lit=null;ByteBuffer unlit=null;try{if(s.lit?(s.mode!=3&&s.mode!=8):(s.mode!=0&&s.mode!=1&&s.mode!=2&&s.mode!=4&&s.mode!=5&&s.mode!=6&&s.mode!=7&&s.mode!=9&&s.mode!=10))throw new IllegalArgumentException();ByteBuffer rgba=s.texture();for(int t=3;t<rgba.remaining();t+=4){int a=rgba.get(t)&255;if(a!=0&&a!=255)throw new IllegalArgumentException();}if(s.lit)lit=new NativeLitWall(packet,world,i,new NativeWorldMesh(packet,world,i));else unlit=NativeSceneDrawPlan.uploadImage(rgba,s.originalIndices(),s.states());}catch(IllegalArgumentException e){out.writeInt(0);rejected++;continue;}out.writeInt(1);for(int v:new int[]{s.width,s.height,s.kind,s.mode,s.originalIndices()!=null?1:0,s.lit?1:0,lit!=null&&lit.curve!=null?1:0})out.writeInt(v);int levels=lit==null?1:16;out.writeInt(levels);for(int level=0;level<levels;level++){buffer(out,lit==null?unlit:lit.variant(level));variants++;}if(lit!=null&&lit.curve!=null){for(double v:lit.curve.endpoints())number(out,v);int[] widths={1,240,3240,3840,16384};out.writeInt(widths.length);for(int width:widths){out.writeInt(width);for(int shade:lit.curve.columns(width))out.writeInt(Integer.reverseBytes(shade));}}accepted++;}}worlds++;}}System.out.println("PASS_PC_WORLD_MATERIAL_EXPORT worlds="+worlds+" accepted="+accepted+" rejected="+rejected+" variants="+variants);}
}
